// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor is the caller who must be current owner; newOwner is the _owner passed in
    function testFuzz_property(address actor, address newOwner) public {
        // keep addresses wide but non-zero for clarity
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));

        // The deployer (this contract) is not the EOA actor; we need actor to be current owner.
        // The contract's owner is set to address(this) (the test contract) because setUp deployed c from this contract.
        // Make actor the owner by having the current owner (this) call setOwner to transfer ownership to actor.
        // Since this test runs in the test contract context, we can call c.setOwner(actor) directly.
        bool ok;
        try c.setOwner(actor) {
            ok = true;
        } catch {
            ok = false;
        }
        // the reference contract should allow this call (current owner is this contract), so ok must be true
        // If this initial transfer somehow reverted, abort the test (narrowing domain) — assume it succeeded
        vm.assume(ok);

        // Now actor is the owner. Have actor call setOwner(newOwner).
        vm.prank(actor);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after an owner calls setOwner(_owner), owner() == _owner
        // Assert that the contract's public owner getter returns exactly the supplied newOwner.
        assertTrue(ok && c.owner() == newOwner);
    }
}

