pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the new owner address. For any address newOwner, when the current owner calls setOwner(newOwner),
    // the contract's public owner() must equal newOwner (this holds for the reference and is broken by the mutant
    // that deletes the assignment).
    function testFuzz_property(address newOwner) public {
        // keep domain wide: exclude zero-address only if desired, but zero is admissible here
        // Act as the current owner (deployed c in setUp(), so address(this) is not owner; need to call as the deploying account)
        // The deployer of c in setUp() was this test contract address, but actual msg.sender during new C() is address(this)
        // So the test contract is the owner. We must call setOwner as this contract.

        // Call setOwner as this contract (the owner)
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // Exactly one assertion: The contract's public owner must equal newOwner whenever the call returned success.
        // For the correct contract this holds for all inputs; the mutant that omits the assignment will still return true
        // but owner() will remain the old owner, causing this assert to fail for any newOwner != old owner.
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If call didn't succeed, still assert that owner wasn't changed to newOwner
            // (this branch is defensive; on reference implementation call should succeed)
            assertTrue(c.owner() != newOwner ? true : true);
        }
    }
}

