pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameters: an arbitrary proxy address that will call setOwner on behalf of some origin, and
    // the target newOwner address that the proxied caller intends to set.
    function testFuzz_property(address proxyCaller, address intendedNewOwner) public {
        // keep addresses in the normal address space (non-zero) to avoid degenerate cases
        vm.assume(proxyCaller != address(0));
        vm.assume(intendedNewOwner != address(0));

        // Deploy a minimal proxy that will call c.setOwner(intendedNewOwner) with msg.sender = proxyCaller
        // We need the proxy's tx.origin to be different from msg.sender to expose the tx.origin-based bug.
        // To achieve that, we will have an externally owned account (EOA) alice perform the call to the proxy,
        // so tx.origin = alice, msg.sender = proxy contract. Fuzzer supplies proxyCaller address to be the
        // proxy contract's code-deployed address; but we cannot deploy at an arbitrary address. Instead,
        // treat proxyCaller as the EOA (caller of the proxy) and deploy a Proxy contract whose constructor
        // records the deployer as the proxy's owner; the EOA (proxyCaller) will call the proxy which in turn
        // calls c. This ensures msg.sender inside C is the proxy contract, while tx.origin is proxyCaller (the EOA).

        // For clarity: use proxyCaller as the EOA that will call a newly deployed Proxy which then calls C.
        // The Proxy contract's address is the msg.sender observed by C; tx.origin will be proxyCaller.

        // Fund the proxy EOA so it can send transactions (vm.prank sets msg.sender but the address must have balance for call)
        vm.deal(proxyCaller, 1 ether);

        // Deploy the Proxy contract (its address will be msg.sender when calling C)
        Proxy proxy = new Proxy(address(c));

        // Have the EOA proxyCaller call the proxy which forwards to c.setOwner(intendedNewOwner)
        vm.prank(proxyCaller);
        proxy.callSetOwner(intendedNewOwner);

        // General rule: when the legitimate current owner calls setOwner(newOwner), the stored owner equals newOwner.
        // In our scenario: initially c.owner() == address(this) at deployment? Actually c was deployed in setUp() by this test
        // contract (address(this)). So the test contract is the owner. We must have the proxy be msg.sender==owner to pass onlyOwner.
        // To make the proxy be the msg.sender and also be the current owner, we need to transfer ownership to the proxy contract first.
        // Adjust flow: instead of above sequence, we should first transfer ownership from this test contract to the proxy contract
        // by calling c.setOwner(address(proxy)) as the legitimate owner (this test contract). Then the proxy (via proxyCaller EOA)
        // will call setOwner(intendedNewOwner). The reference contract will set owner to intendedNewOwner; the mutant will set owner to tx.origin (proxyCaller),
        // so the property is violated when proxyCaller != intendedNewOwner.

        // Reset state: redeploy and execute correct sequence with proper ownership transfer.
        // Re-deploy c fresh to ensure predictable owner (test contract)
        c = new C();
        // Deploy a fresh proxy linked to this new c
        Proxy proxy2 = new Proxy(address(c));

        // Transfer ownership from this test contract (current owner) to the proxy contract so proxy contract can call onlyOwner functions
        bool ok;
        try c.setOwner(address(proxy2)) { ok = true; } catch { ok = false; }
        // The reference always allows this; mutant may have changed semantics but still onlyOwner guard remains. Assert that transfer succeeded in the reference context.
        assertTrue(ok, "initial transfer to proxy failed");

        // Now have the EOA proxyCaller call the proxy which forwards to c.setOwner(intendedNewOwner)
        vm.prank(proxyCaller);
        proxy2.callSetOwner(intendedNewOwner);

        // Exactly one assertion: after a legitimate owner (the proxy contract) calls setOwner(intendedNewOwner),
        // the public getter owner() must equal the intendedNewOwner. The mutant that sets owner = tx.origin will violate this when
        // tx.origin (proxyCaller) != intendedNewOwner. This assertion holds for the reference for ALL inputs; the mutant breaks for some inputs.
        assertTrue(c.owner() == intendedNewOwner, "owner was not set to the intendedNewOwner");
    }
}

// Minimal proxy helper: forwards a call to C.setOwner(address) using a simple call from this contract.
contract Proxy {
    address public target;
    constructor(address _target) {
        target = _target;
    }
    function callSetOwner(address _owner) public {
        // Forward the call to the target contract's setOwner function
        // We use a low-level call to invoke the public function setOwner(address)
        (bool success, ) = target.call(abi.encodeWithSignature("setOwner(address)", _owner));
        require(success, "forward failed");
    }
}

