pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: proxyCaller is the address of a contract that will call c.setOwner(target)
    // target is the address we intend to set as owner
    function testFuzz_property(address proxyCaller, address target) public {
        // keep addresses non-zero to avoid degenerate cases
        vm.assume(proxyCaller != address(0));
        vm.assume(target != address(0));

        // Deploy a proxy contract whose sole purpose is to call c.setOwner(target) from itself.
        // This ensures msg.sender == address(proxy) but tx.origin == the EOA that transacted.
        Proxy p = new Proxy(c);

        // Ensure the proxy's address matches the fuzzed proxyCaller address only in the sense
        // that fuzzed proxyCaller is used as the EOA transacting; we cannot force the deployed
        // proxy's address to equal proxyCaller, so instead treat proxyCaller as the EOA (tx.origin)
        // that will perform the transaction. We must ensure proxyCaller (an EOA) has funds to send.

        // Give the EOA (proxyCaller) some ETH so it can send the transaction
        vm.deal(proxyCaller, 1 ether);

        // The contract c's constructor set owner = msg.sender (the test contract). We need the
        // test contract to be the current owner to allow calling setOwner via the proxy.
        // The test contract is already the deployer, so it is owner. We'll have the test contract
        // instruct the proxy to invoke setOwner(target) but the actual tx will be sent by proxyCaller
        // as tx.origin by using vm.prank(proxyCaller) which sets tx.origin and msg.sender for the
        // top-level call; inside Proxy the msg.sender will be the proxy (as it does a call), and
        // tx.origin will be proxyCaller. This models a proxied call where msg.sender != tx.origin.

        // In the reference contract: after the proxied call completes, owner == target.
        // In the mutant that assigns owner = tx.origin, owner == proxyCaller instead, differing when
        // proxyCaller != target. We therefore assert the universal property that after the proxied
        // call, owner() == target. The reference satisfies this for all inputs; the mutant fails
        // for some inputs (when proxyCaller != target), which the fuzzer will find.

        // Execute the proxied call with tx.origin = proxyCaller
        vm.prank(proxyCaller);
        p.callSetOwner(target);

        // Exactly one assertion: the owner getter must equal the provided target address
        assertTrue(c.owner() == target);
    }
}

// Minimal proxy that calls c.setOwner(target) from itself (so msg.sender == address(this)).
contract Proxy {
    C immutable c;
    constructor(C _c) { c = _c; }
    function callSetOwner(address _owner) external {
        // call c.setOwner from this contract; msg.sender for c will be this Proxy,
        // but tx.origin will be the original EOA that initiated the transaction.
        c.setOwner(_owner);
    }
}

