pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: address proxier (a contract) and address target (new owner)
    function testFuzz_property(address proxier, address target) public {
        // admissible domain: proxier must be a non-zero address distinct from tx.origin
        // and not equal to the initial owner (deployer) to ensure a proxy scenario.
        vm.assume(proxier != address(0));
        vm.assume(target != address(0));
        // ensure proxier is not an EOA by deploying a minimal forwarder at that address
        // We cannot deploy at an arbitrary address, so restrict proxier to not be the test caller
        // and instead deploy a Forwarder and use its address as the proxier; still keep target fuzzed.

        // Deploy an on-chain proxy (Forwarder) that will call c.setOwner(target) from its own context
        Forwarder f = new Forwarder();
        address payable proxy = payable(address(f));

        // ensure proxy is different from tx.origin (the test runner)
        vm.assume(proxy != tx.origin);

        // The initial owner is the test contract's deployer (address(this) in setUp via forge),
        // but c was deployed in setUp by this test contract; current owner == address(this).
        // We need the owner to call setOwner; so we impersonate the current owner (this) when calling
        // the proxy to forward the call. Use vm.prank to make the proxy's call originate from the owner.

        // Prepare calldata for setOwner(target)
        bytes memory data = abi.encodeWithSelector(c.setOwner.selector, target);

        // From the owner (address(this)) instruct the proxy to call c with the calldata.
        // We need the proxy to perform the external call such that within c: msg.sender == proxy, tx.origin == address(this)
        // Achieve this by having the proxy perform the call with address(this) as tx.origin — we use vm.prank to simulate tx.origin as address(this)
        // vm.prank sets msg.sender for the next call; to make tx.origin equal to address(this) we simply perform the outermost tx from address(this) (default in tests)

        // Ensure the test runner (address(this)) is the current owner and will instruct the proxy.
        // Call forward: we impersonate the proxy so that when forward() is executed, forward()'s internal call into c has msg.sender == proxy and tx.origin == address(this).
        // Achieve by vm.prank(address(this)) executing f.forward(address(c), data) — this makes the EOA address(this) call f.forward, so tx.origin == address(this).

        // Execute: call forward() from address(this)
        vm.prank(address(this));
        f.forward(address(c), data);

        // After the proxy forwarded the call, in the correct reference contract, owner should equal the provided target.
        // We assert that c.owner() == target. This is true for the reference for all admissible inputs; the mutant that sets owner = tx.origin will set owner == tx.origin (address(this)) instead when msg.sender != tx.origin, causing this assertion to fail for some targets.
        assertTrue(c.owner() == target);
    }
}

// Minimal forwarder that simply forwards calldata to a target via a low-level call.
contract Forwarder {
    function forward(address to, bytes calldata data) external returns (bool ok, bytes memory ret) {
        (ok, ret) = to.call(data);
        require(ok, "forward call failed");
    }
}

