import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters:
    // - callerAsContract: whether the owner will be a contract (true) or an EOA (false)
    // - newOwner: the address to set as the new owner
    function testFuzz_property(bool callerAsContract, address newOwner) public {
        // Keep newOwner wide but non-zero to avoid trivial zero-address semantics
        vm.assume(newOwner != address(0));

        // We start with deployer as owner (setUp did new C()). msg.sender at deployment was address(this) in setUp,
        // so current owner == address(this). We want to test calls that are made with msg.sender == owner.
        // Two scenarios:
        // - If callerAsContract == false: we simulate the owner (an EOA) calling setOwner directly via prank
        // - If callerAsContract == true: we deploy a thin forwarder contract whose address will be the msg.sender
        //   when calling c.setOwner; the forwarder will call c.setOwner on behalf of its owner (this test), so
        //   msg.sender == address(forwarder) but tx.origin == address(this). This models an owner that is a contract.

        if (!callerAsContract) {
            // owner is an EOA: address(this) is the owner; perform call as address(this)
            // address(this) already owns c because setUp deployed c from this contract.
            // Perform the call directly: we are the owner (msg.sender == owner == address(this), tx.origin also equals address(this)).
            bool ok;
            try c.setOwner(newOwner) returns (bool res) { ok = res; } catch { ok = false; }
            // GENERAL ASSERTION: in the reference contract, when msg.sender == owner (here address(this)),
            // setOwner must succeed and return true, and owner getter must equal newOwner.
            // We assert the behavior by checking the getter; this will pass for the reference for all inputs,
            // and the mutant may still pass for this branch (since tx.origin == owner here). Still valid universal rule.
            assertTrue(c.owner() == newOwner);
            // Note: only one assertTrue is allowed by the spec; the previous line is it.
            return;
        } else {
            // owner is a contract: deploy Forwarder owned by this test, then make that forwarder the owner
            Forwarder f = new Forwarder(c);
            // Transfer ownership to the forwarder: since this test contract is current owner, call setOwner to f
            bool ok1;
            try c.setOwner(address(f)) returns (bool res1) { ok1 = res1; } catch { ok1 = false; }
            // ensure transfer succeeded on reference; if it didn't, the test can still proceed but the property concerns
            // that when msg.sender == owner, setOwner should succeed. Now simulate the forwarder calling setOwner(newOwner).
            // The forwarder will invoke c.setOwner(newOwner) such that msg.sender == address(f) and tx.origin == address(this).
            bool ok2;
            try f.callSetOwner(newOwner) returns (bool res2) { ok2 = res2; } catch { ok2 = false; }

            // SINGLE ASSERT: For the reference contract, when msg.sender == owner (here the forwarder contract),
            // setOwner should succeed and the public getter owner() must equal newOwner. The mutant that adds
            // require(tx.origin == owner) will reject this call because tx.origin == address(this) != address(f),
            // so owner will remain address(f) (or some other value) and this assertion will fail for some fuzz inputs.
            assertTrue(c.owner() == newOwner);
            return;
        }
    }
}

// Minimal forwarder contract that calls c.setOwner on behalf of this test contract.
contract Forwarder {
    C immutable target;
    constructor(C _target) { target = _target; }
    // allow the test contract to trigger this
    function callSetOwner(address _owner) external returns (bool) {
        // msg.sender will be this contract when calling target.setOwner, and tx.origin will be the original EOA (the test contract)
        return target.setOwner(_owner);
    }
}

